import 'package:flutter/material.dart';import '../models/recordatorio.dart';import '../services/api_service.dart';
class RecordatorioForm extends StatefulWidget{final Recordatorio? item;const RecordatorioForm({super.key,this.item});@override State<RecordatorioForm> createState()=>_RecordatorioFormState();}
class _RecordatorioFormState extends State<RecordatorioForm>{final form=GlobalKey<FormState>();late final title=TextEditingController(text:widget.item?.titulo??'');late final desc=TextEditingController(text:widget.item?.descripcion??'');late DateTime date=widget.item?.fechaHora??DateTime.now().add(const Duration(hours:1));bool busy=false;Future<void> pick()async{final d=await showDatePicker(context:context,initialDate:date,firstDate:DateTime.now().subtract(const Duration(days:365)),lastDate:DateTime(2100));if(d==null)return;final t=await showTimePicker(context:context,initialTime:TimeOfDay.fromDateTime(date));if(t!=null)setState(()=>date=DateTime(d.year,d.month,d.day,t.hour,t.minute));}Future<void> submit()async{if(!form.currentState!.validate())return;setState(()=>busy=true);try{final data={'titulo':title.text.trim(),'descripcion':desc.text.trim(),'fechaHora':date.toIso8601String()};if(widget.item==null){await ApiService().create(data);}else{await ApiService().update(widget.item!.id,data);}if(mounted)Navigator.pop(context,true);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.item==null?'Nuevo recordatorio':'Editar recordatorio')),body:Padding(padding:const EdgeInsets.all(20),child:Form(key:form,child:Column(children:[TextFormField(controller:title,maxLength:150,decoration:const InputDecoration(labelText:'Título'),validator:(v)=>v==null||v.trim().isEmpty?'Ingresa un título':null),TextField(controller:desc,decoration:const InputDecoration(labelText:'Descripción (opcional)')),ListTile(title:Text('Fecha y hora: ${date.day}/${date.month}/${date.year} ${TimeOfDay.fromDateTime(date).format(context)}'),trailing:const Icon(Icons.calendar_month),onTap:pick),const Spacer(),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Guardando...':'Guardar'))]))));}}